import{_ as r,I as i,o,c as l,j as a,a as d,J as n,a4 as p}from"./chunks/framework.cM03Lg2X.js";const k=JSON.parse('{"title":"项目与实验","description":"按状态与复用价值总结技术棚屋中的 Side Project 和技术实验。","frontmatter":{"title":"项目与实验","description":"按状态与复用价值总结技术棚屋中的 Side Project 和技术实验。"},"headers":[],"relativePath":"shed/projects.md","filePath":"shed/projects.md","lastUpdated":1786332289000}'),s={name:"shed/projects.md"};function c(h,e,b,m,f,u){const t=i("StatGrid");return o(),l("div",null,[e[0]||(e[0]=a("h1",{id:"项目与实验",tabindex:"-1"},[d("项目与实验 "),a("a",{class:"header-anchor",href:"#项目与实验","aria-label":"Permalink to “项目与实验”"},"​")],-1)),e[1]||(e[1]=a("p",null,"“技术棚屋”不是项目展示墙，而是保留每个项目的目标、关键决策、当前状态和可复用资产。以下内容来自 Notion「项目列表」，按完成、探索、归档重新分组。",-1)),n(t,{title:"项目状态",items:[{value:"4",label:"已完成"},{value:"1",label:"探索中"},{value:"1",label:"已归档"},{value:"5",label:"主要技术栈"}]}),e[2]||(e[2]=p('<h2 id="已完成" tabindex="-1">已完成 <a class="header-anchor" href="#已完成" aria-label="Permalink to “已完成”">​</a></h2><h3 id="daily-input-stats" tabindex="-1">daily-input-stats <a class="header-anchor" href="#daily-input-stats" aria-label="Permalink to “daily-input-stats”">​</a></h3><p>本地 macOS 统计应用，按天记录键盘事件数、鼠标点击数和屏幕未休眠时的空闲时间。使用 Swift Package Manager + AppKit，数据按日写入本地 JSON，自绘紧凑仪表盘。</p><p>最重要的设计边界是隐私：只统计 <code>keyDown</code> / <code>mouseDown</code> 事件数量，不保存具体按键内容；空闲时间仅在屏幕未休眠且系统空闲超过 60 秒时累计。</p><h3 id="codex-stats-menubar" tabindex="-1">codex-stats-menubar <a class="header-anchor" href="#codex-stats-menubar" aria-label="Permalink to “codex-stats-menubar”">​</a></h3><p>macOS 菜单栏 Codex 使用统计工具。它解析本地 JSONL，提供 Overview / Models 面板、热力图、模型占比和费用估算，使用 SwiftUI + AppKit <code>NSStatusBar</code> 打包为 <code>.app</code>。</p><p>可复用决策：桌面统计工具保持本地解析；运行入口统一放到 <code>scripts/*.sh</code>；AppKit 负责菜单栏生命周期，SwiftUI 负责内容界面。</p><h3 id="service-up" tabindex="-1">service-up <a class="header-anchor" href="#service-up" aria-label="Permalink to “service-up”">​</a></h3><p>面向本地多个服务的 Textual TUI，支持统一启停、日志查看、CPU / MEM / 端口监控，以及 local、dev、ontest、prod Profile 切换。</p><p>工程亮点包括：</p><ul><li><code>subprocess.Popen</code> 管理进程，<code>psutil</code> 监控资源；</li><li>TOML 配置与 ProfileManager 生成 <code>env.sh</code>；</li><li>token、JWT、base64 日志脱敏；</li><li>集中日志与统一脚本入口；</li><li>从 v0.1.0 的 33 个测试增长到 v0.2.0 的 42 个测试。</li></ul><h3 id="pixel-pet" tabindex="-1">pixel-pet <a class="header-anchor" href="#pixel-pet" aria-label="Permalink to “pixel-pet”">​</a></h3><p>Go + Ebitengine 桌面像素宠物。最终形成透明无边框悬浮窗、属性与成长系统、JSON 存档、20 款皮肤、18 款配饰、22 种动作和 105 句台词。</p><p>最有复用价值的是 Pixel Delta 动画：每帧只记录发生变化的像素，而不是复制整张 16×16 精灵矩阵，使动作定义代码量减少约 90%。最终二进制约 12 MB、零运行时依赖。</p><h2 id="探索中" tabindex="-1">探索中 <a class="header-anchor" href="#探索中" aria-label="Permalink to “探索中”">​</a></h2><h3 id="work-summary" tabindex="-1">work-summary <a class="header-anchor" href="#work-summary" aria-label="Permalink to “work-summary”">​</a></h3><p>目标是收集 Git 提交和 AI 对话记录，生成每日工作总结。Notion 当前只有项目摘要，没有足够的实现日志或验证结果，因此保留为“探索中”，不补写未发生的架构与成效。</p><p>下一次总结需要补齐：数据来源边界、去重规则、隐私脱敏、日报生成与发布验证。</p><h2 id="已归档" tabindex="-1">已归档 <a class="header-anchor" href="#已归档" aria-label="Permalink to “已归档”">​</a></h2><h3 id="memflow-paper-memifc" tabindex="-1">memflow-paper / MemIFC <a class="header-anchor" href="#memflow-paper-memifc" aria-label="Permalink to “memflow-paper / MemIFC”">​</a></h3><p>项目尝试把信息流控制用于 Agent 持久记忆安全，经历了论文调研、形式化设计、baseline 实现和多轮评审，最终主动归档。</p><p>归档原因不是“实现没完成”，而是核心假设经不起验证：</p><ul><li><code>derived_from</code> 链会导致 taint explosion；</li><li>trust laundering 依赖真实系统并不存在的 source-based trust 标签；</li><li>谱分析定理错误地把线性方法用于非线性 min-label 操作；</li><li>写侧 trust downgrade 本质上没有超出既有 Biba 模型。</li></ul><p>这次失败留下了更重要的研究方法：先验证攻击与系统假设，再写大量代码；应用旧理论不自动等于创新；自造数据不能替代真实系统证据；内部严苛评审应早于投稿叙事。</p><p>可复用资产包括 InjecAgent / FreshQA 数据加载器、tool-calling agent 框架、LLM-judge 评估与 ChromaDB Memory Provider。</p><h2 id="跨项目共性" tabindex="-1">跨项目共性 <a class="header-anchor" href="#跨项目共性" aria-label="Permalink to “跨项目共性”">​</a></h2><table tabindex="0"><thead><tr><th>经验</th><th>来自项目</th><th>可复用判断</th></tr></thead><tbody><tr><td>本地优先、最小数据</td><td>daily-input-stats、codex-stats</td><td>统计工具不应默认采集原始敏感内容</td></tr><tr><td>原生容器 + 声明式 UI</td><td>两个 Swift 项目</td><td>生命周期和视图职责分离</td></tr><tr><td>统一脚本入口</td><td>codex-stats、service-up</td><td>降低环境差异和运行摩擦</td></tr><tr><td>表达结构而不是复制帧</td><td>pixel-pet</td><td>对低分辨率动画使用 delta 表示</td></tr><tr><td>尽早证伪</td><td>memflow-paper</td><td>研究项目优先验证前提与真实影响</td></tr></tbody></table><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li><a href="https://app.notion.com/p/33c3a54bd6b481f8b6c0df28e8121d21" target="_blank" rel="noreferrer">Notion：项目列表</a></li><li><a href="https://app.notion.com/p/daily-input-stats-macOS-Swift-36b3a54bd6b481bdb029dc27012bf4ca" target="_blank" rel="noreferrer">Notion：daily-input-stats</a></li><li><a href="https://app.notion.com/p/codex-stats-menubar-macOS-Codex-36b3a54bd6b481409d74ec22fee5032c" target="_blank" rel="noreferrer">Notion：codex-stats-menubar</a></li><li><a href="https://app.notion.com/p/service-up-TUI-Profile-33c3a54bd6b4816b8e8cf9db0e2a1d52" target="_blank" rel="noreferrer">Notion：service-up</a></li><li><a href="https://app.notion.com/p/pixel-pet-33c3a54bd6b481e5b68bf3ff8b87f365" target="_blank" rel="noreferrer">Notion：pixel-pet</a></li><li><a href="https://app.notion.com/p/work-summary-git-AI-33d3a54bd6b481dd9f4cda362efa76b9" target="_blank" rel="noreferrer">Notion：work-summary</a></li><li><a href="https://app.notion.com/p/memflow-paper-Agent-memory-security-via-OS-inspired-IFC-33e3a54bd6b48164900bdbbb85ae78f3" target="_blank" rel="noreferrer">Notion：memflow-paper</a></li></ul>',29))])}const _=r(s,[["render",c]]);export{k as __pageData,_ as default};
